local function numbers(a, b, c)
	return NumberSequence.new({
		NumberSequenceKeypoint.new(0, a),
		NumberSequenceKeypoint.new(0.5, b),
		NumberSequenceKeypoint.new(1, c),
	})
end

local function size(emitter, a, b, c)
	emitter.Size = numbers(a, b, c)
end

local function fade(emitter, a, b)
	emitter.Transparency = numbers(a, b, 1)
end

local function burst(emitter, count)
	emitter.Rate = 0
	emitter:SetAttribute("EmitCount", count)
end

local function flow(emitter, rate)
	emitter.Rate = rate
	emitter:SetAttribute("EmitCount", 0)
end

local function configure(emitter, spec)
	local recipe = spec.recipe
	emitter.Texture = spec.texture
	emitter.Color = ColorSequence.new(Color3.fromRGB(table.unpack(spec.color)))
	emitter.Enabled = true
	emitter.LightEmission = 0.45
	emitter.LightInfluence = 0
	emitter.Brightness = 0.7
	emitter.Orientation = Enum.ParticleOrientation.FacingCamera
	emitter.EmissionDirection = Enum.NormalId.Top
	emitter.SpreadAngle = Vector2.new(35, 35)
	emitter.Shape = Enum.ParticleEmitterShape.Sphere
	emitter.ShapeStyle = Enum.ParticleEmitterShapeStyle.Volume
	emitter.ShapeInOut = Enum.ParticleEmitterShapeInOut.Outward
	emitter.ShapePartial = 1
	emitter.Lifetime = NumberRange.new(1)
	emitter.Speed = NumberRange.new(0)
	emitter.Rotation = NumberRange.new(0)
	emitter.RotSpeed = NumberRange.new(0)
	emitter.Acceleration = Vector3.zero
	emitter.Drag = 0
	size(emitter, 1, 1, 0)
	fade(emitter, 0.05, 0.25)

	if recipe == "flame" then
		flow(emitter, 8)
		emitter.Lifetime = NumberRange.new(0.6, 1)
		emitter.Speed = NumberRange.new(2.5, 4.5)
		emitter.RotSpeed = NumberRange.new(-30, 30)
		size(emitter, 1, 2.4, 0)
		emitter.Brightness = 0.65
	elseif recipe == "smoke" or recipe == "cloud" or recipe == "shadow" then
		flow(emitter, recipe == "cloud" and 2 or 4)
		emitter.Lifetime = NumberRange.new(2.2, 3.2)
		emitter.Speed = NumberRange.new(1, 2)
		if recipe == "cloud" then
			emitter.EmissionDirection = Enum.NormalId.Right
			emitter.SpreadAngle = Vector2.new(12, 12)
		end
		emitter.Drag = 0.6
		emitter.RotSpeed = NumberRange.new(-20, 20)
		emitter.LightEmission = recipe == "shadow" and 0.2 or 0.05
		emitter.LightInfluence = 0.5
		emitter.Brightness = 0.45
		size(emitter, 1.5, recipe == "cloud" and 5.5 or recipe == "shadow" and 3.2 or 4.2, recipe == "cloud" and 6 or recipe == "shadow" and 3.6 or 5)
		fade(emitter, recipe == "shadow" and 0.5 or 0.35, recipe == "shadow" and 0.65 or 0.5)
	elseif recipe == "dust" then
		burst(emitter, 10)
		emitter.Lifetime = NumberRange.new(0.8, 1.3)
		emitter.Speed = NumberRange.new(4, 7)
		emitter.SpreadAngle = Vector2.new(180, 180)
		emitter.Drag = 2
		emitter.LightEmission = 0.05
		size(emitter, 1.2, 3.5, 0)
		fade(emitter, 0.3, 0.5)
	elseif recipe == "bubble" then
		flow(emitter, 4)
		emitter.Lifetime = NumberRange.new(2, 3)
		emitter.Speed = NumberRange.new(0.8, 1.4)
		emitter.Acceleration = Vector3.new(0, 0.6, 0)
		emitter.LightEmission = 0.1
		emitter.LightInfluence = 0.5
		size(emitter, 0.6, 1.1, 0)
		fade(emitter, 0.2, 0.3)
	elseif recipe == "leaf" or recipe == "snow" then
		flow(emitter, recipe == "leaf" and 4 or 6)
		emitter.EmissionDirection = Enum.NormalId.Bottom
		emitter.Lifetime = NumberRange.new(2.5, 3.5)
		emitter.Speed = NumberRange.new(1.2, 2.3)
		emitter.SpreadAngle = Vector2.new(70, 70)
		emitter.Rotation = NumberRange.new(-180, 180)
		emitter.RotSpeed = NumberRange.new(-70, 70)
		emitter.LightEmission = 0.1
		size(emitter, 0.6, recipe == "snow" and 0.9 or 1.1, 0.55)
	elseif recipe == "debris" then
		burst(emitter, 12)
		emitter.Lifetime = NumberRange.new(0.8, 1.2)
		emitter.Speed = NumberRange.new(8, 14)
		emitter.SpreadAngle = Vector2.new(180, 180)
		emitter.Acceleration = Vector3.new(0, -20, 0)
		emitter.Rotation = NumberRange.new(-180, 180)
		emitter.RotSpeed = NumberRange.new(-100, 100)
		emitter.LightEmission = 0.1
		size(emitter, 0.65, 1.1, 0)
	elseif recipe == "lightning" then
		burst(emitter, 4)
		emitter.Lifetime = NumberRange.new(0.3, 0.5)
		emitter.Speed = NumberRange.new(2, 5)
		emitter.SpreadAngle = Vector2.new(180, 180)
		emitter.Rotation = NumberRange.new(-180, 180)
		emitter.LightEmission = 0.85
		emitter.Brightness = 1.1
		size(emitter, 3.5, 5.2, 0)
	elseif recipe == "spark" then
		flow(emitter, 7)
		emitter.Lifetime = NumberRange.new(0.6, 1)
		emitter.Speed = NumberRange.new(4, 8)
		emitter.SpreadAngle = Vector2.new(100, 100)
		emitter.Rotation = NumberRange.new(-180, 180)
		emitter.LightEmission = 0.8
		size(emitter, 0.65, 1.15, 0)
	elseif recipe == "slash" or recipe == "impact" or recipe == "blood" then
		burst(emitter, 1)
		emitter.Lifetime = NumberRange.new(recipe == "slash" and 0.45 or 0.55)
		emitter.LightEmission = recipe == "blood" and 0.05 or 0.65
		size(emitter, recipe == "blood" and 2.8 or 3.2, 5.3, 0)
		fade(emitter, 0.08, 0.18)
	elseif recipe == "ripple" or recipe == "ring" then
		burst(emitter, 1)
		emitter.Lifetime = NumberRange.new(0.8)
		emitter.LightEmission = 0.55
		size(emitter, 1.7, 5.2, 7)
		fade(emitter, 0.1, 0.35)
	elseif recipe == "sigil" or recipe == "glyph" then
		if recipe == "glyph" then flow(emitter, 1.2) else burst(emitter, 1) end
		emitter.Lifetime = NumberRange.new(2)
		emitter.RotSpeed = NumberRange.new(recipe == "glyph" and 0 or 20)
		emitter.LightEmission = 0.55
		size(emitter, recipe == "glyph" and 1.6 or 3.6, recipe == "glyph" and 2.4 or 5.2, recipe == "glyph" and 0 or 5.2)
		fade(emitter, 0.12, 0.14)
	elseif recipe == "shield" then
		burst(emitter, 1)
		emitter.Lifetime = NumberRange.new(0.8)
		emitter.LightEmission = 0.6
		size(emitter, 2.5, 4.5, 5)
		fade(emitter, 0.08, 0.3)
	elseif recipe == "splash" then
		burst(emitter, 8)
		emitter.Lifetime = NumberRange.new(0.65, 1)
		emitter.Speed = NumberRange.new(4, 7)
		emitter.SpreadAngle = Vector2.new(180, 180)
		emitter.Acceleration = Vector3.new(0, -12, 0)
		emitter.LightEmission = 0.25
		size(emitter, 1, 1.7, 0)
	elseif recipe == "beam" then
		burst(emitter, 3)
		emitter.Lifetime = NumberRange.new(0.45, 0.7)
		emitter.Speed = NumberRange.new(5, 9)
		emitter.SpreadAngle = Vector2.new(30, 30)
		emitter.LightEmission = 0.75
		size(emitter, 1.2, 2.5, 0)
	elseif recipe == "vortex" then
		burst(emitter, 1)
		emitter.Lifetime = NumberRange.new(1.3)
		emitter.RotSpeed = NumberRange.new(90)
		emitter.LightEmission = 0.55
		size(emitter, 2.8, 5.1, 0)
	elseif recipe == "heart" or recipe == "symbol" or recipe == "orb" then
		flow(emitter, recipe == "orb" and 3 or 2.5)
		emitter.Lifetime = NumberRange.new(1.4, 2.1)
		emitter.Speed = NumberRange.new(1, 2)
		emitter.RotSpeed = NumberRange.new(-20, 20)
		size(emitter, 0.7, recipe == "orb" and 2.5 or 1.7, 0)
	elseif recipe == "creature" then
		flow(emitter, 2)
		emitter.EmissionDirection = Enum.NormalId.Right
		emitter.SpreadAngle = Vector2.new(12, 12)
		emitter.Lifetime = NumberRange.new(1.5, 2)
		emitter.Speed = NumberRange.new(1.4, 2.4)
		emitter.Rotation = NumberRange.new(-12, 12)
		emitter.LightEmission = 0.2
		size(emitter, 1.1, 1.8, 0)
	end

	if spec.kind == "FlipBook" then
		emitter.FlipbookLayout = Enum.ParticleFlipbookLayout[spec.layout]
		emitter.FlipbookMode = Enum.ParticleFlipbookMode.OneShot
		local frames = spec.layout == "Grid8x8" and 64 or spec.layout == "Grid2x2" and 4 or 16
		local fps = spec.recipe == "glyph" and 1 or spec.recipe == "debris" and 1 or frames == 64 and 48 or frames == 4 and 8 or 20
		emitter.FlipbookFramerate = NumberRange.new(fps)
		emitter.Lifetime = NumberRange.new(spec.recipe == "glyph" and 1.1 or spec.recipe == "debris" and 1.1 or frames / fps)
		if spec.recipe == "glyph" or spec.recipe == "debris" then
			emitter.FlipbookStartRandom = true
		end
		if spec.recipe == "smoke" or spec.recipe == "cloud" then
			size(emitter, 1.5, 4.5, 5)
		elseif spec.recipe == "flame" then
			size(emitter, 1.1, 2.8, 0)
		elseif spec.recipe == "impact" or spec.recipe == "slash" or spec.recipe == "lightning" or spec.recipe == "ring" or spec.recipe == "ripple" then
			size(emitter, 3.2, 5.3, 5.5)
		elseif spec.recipe == "debris" then
			size(emitter, 0.65, 1.1, 0)
		end
	end
	if string.sub(spec.card, 1, 5) == "Black" then
		emitter.LightEmission = 0
		emitter.Brightness = 1
		if spec.card == "BlackFire1" then
			size(emitter, 0.7, 1.7, 0)
		elseif spec.card == "BlackDust1" then
			size(emitter, 0.5, 0.75, 0)
		end
	end
	if spec.kind == "FlipBook" and string.sub(spec.card, 1, 7) == "Sparkle" then
		emitter.LightEmission = 1
		emitter.Brightness = 1.2
		size(emitter, 1.5, 2.5, 0)
	end
end

local function promptGui(prompt)
	local gui = Instance.new("BillboardGui")
	gui.Name = "Prompt"
	gui.Size = UDim2.fromOffset(180, 72)
	gui.StudsOffset = Vector3.new(0, 8, 0)
	gui.MaxDistance = 40
	gui.LightInfluence = 0
	local text = Instance.new("TextLabel")
	text.Size = UDim2.fromScale(1, 1)
	text.BackgroundColor3 = Color3.fromRGB(16, 20, 28)
	text.BackgroundTransparency = 0.22
	text.TextColor3 = Color3.new(1, 1, 1)
	text.TextSize = 12
	text.TextWrapped = true
	text.Font = Enum.Font.GothamMedium
	text.Text = prompt
	text.Parent = gui
	return gui
end

function Expansion.build(first, last)
	first = first or 1
	last = math.min(last or #effects, #effects)
	local dataset = Workspace.Particles.Dataset
	local floors = Workspace:FindFirstChild("DatasetReviewFloors") or Instance.new("Folder")
	floors.Name = "DatasetReviewFloors"
	floors.Parent = Workspace
	local made = 0
	for i = first, last do
		local spec = effects[i]
		local family = dataset:FindFirstChild(spec.family)
		if not family then
			family = Instance.new("Folder")
			family.Name = spec.family
			family.Parent = dataset
		end
		local name = spec.id .. "_V01_Base"
		if not family:FindFirstChild(name) then
			local x = -420 + spec.column * 40
			local z = -520 + spec.row * 40
			local floor = Instance.new("Part")
			floor.Name = spec.id .. "_CIXRaised"
			floor.Anchored = true
			floor.Size = Vector3.new(24, 0.5, 24)
			floor.Position = Vector3.new(x, 80, z)
			floor.Color = spec.category == "Shadow" and Color3.fromRGB(189, 194, 202) or Color3.fromRGB(46, 53, 65)
			floor.Material = Enum.Material.Slate
			floor.Parent = floors

			local attachment = Instance.new("Attachment")
			attachment.Name = name
			local height = (spec.recipe == "leaf" or spec.recipe == "snow") and 94 or spec.recipe == "cloud" and 90 or 84
			attachment.CFrame = CFrame.new(x, height, z)
			attachment:SetAttribute("Category", spec.category)
			attachment:SetAttribute("Split", spec.split)
			attachment.Parent = family

			local emitter = Instance.new("ParticleEmitter")
			emitter.Name = "ParticleEmitter"
			configure(emitter, spec)
			emitter.Parent = attachment
			promptGui(spec.prompt).Parent = attachment
			made += 1
		end
	end
	return made
end

function Expansion.focus(id)
	for _, spec in ipairs(effects) do
		if spec.id == id then
			local attachment = Workspace.Particles.Dataset[spec.family][id .. "_V01_Base"]
			local emitter = attachment.ParticleEmitter
			local position = attachment.WorldPosition
			local camera = Workspace.CurrentCamera
			camera.CameraType = Enum.CameraType.Scriptable
			camera.CFrame = CFrame.lookAt(position + Vector3.new(0, 4, 17), position + Vector3.new(0, 2, 0))
			camera.FieldOfView = 50
			local count = emitter:GetAttribute("EmitCount")
			if count and count > 0 then emitter:Emit(count) end
			return attachment
		end
	end
	error("Unknown CIX ID: " .. tostring(id))
end

function Expansion.list()
	return effects
end

return Expansion
